import { create } from 'zustand';

type CartItem = { id: string; name: string; price: number };

type CartState = {
  items: CartItem[];
  addItem: (item: CartItem) => void;
  removeItem: (id: string) => void;
  total: () => number;
};

export const useCartStore = create<CartState>((set, get) => ({
  items: [],
  addItem: (item) => set((state) => ({ items: [...state.items, item] })),
  removeItem: (id) => set((state) => ({ items: state.items.filter((i) => i.id !== id) })),
  total: () => get().items.reduce((sum, item) => sum + item.price, 0),
}));

import { useCartStore } from './stores/cartStore';

// Re-renders only when items.length changes
export function CartBadge() {
  const count = useCartStore((state) => state.items.length);
  return <span>{count}</span>;
}

// Multiple values: use shallow equality to avoid a render per new object
import { useShallow } from 'zustand/react/shallow';

export function CartSummary() {
  const { items, total } = useCartStore(
    useShallow((state) => ({ items: state.items, total: state.total() }))
  );
  return <p>{items.length} items — ${total}</p>;
}

import { create } from 'zustand';
import { persist } from 'zustand/middleware';

export const useSettingsStore = create(
  persist(
    (set) => ({
      theme: 'light' as 'light' | 'dark',
      toggleTheme: () => set((s) => ({ theme: s.theme === 'light' ? 'dark' : 'light' })),
    }),
    { name: 'settings', partialize: (state) => ({ theme: state.theme }) }
  )
);

